public struct FfiConverterTypeRecachedError: FfiConverterRustBuffer {
    typealias SwiftType = RecachedError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RecachedError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Storage(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Command(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .NotUtf8(
            key: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RecachedError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Storage(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Command(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .NotUtf8(key):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(key, into: &buf)
            
        }
    }
}


